input.command:
cd ~/cp-roles/harness-python && python3 -c "
import json;d=json.load(open('harnesses/stages.json'))
from collections import Counter
pk=Counter();sk=Counter();ik=Counter();stk=Counter();qk=Counter();par=Counter()
for p in d['problems']:
  pk.update(p.keys())
  for s in p['subproblems']:
    sk.update(s.keys())
    for i in s['instances']:
      ik.update(i.keys()); par.update(i['parameters'].keys())
    for st in s['stages']:
      stk.update(st.keys())
      for q in st['queries']: qk.update(q.keys())
print(pk);print(sk);print(ik);print(par);print(stk);print(qk)
for p in d['problems']:
  for k in p:
    if k not in ('problem','file','title','effects','subproblems'): print(p['problem'],k,json.dumps(p[k])[:400])
  for s in p['subproblems']:
    for k in s:
      if k not in ('id','line','title','unknowns','readings','instances','stages'): print(s['id'],k,json.dumps(s[k])[:600])
    for st in s['stages']:
      for k in st:
        if k not in ('stage','line','kind','description','queries','commit','spawns'): print(s['id'],st['stage'],k,json.dumps(st[k])[:600])
      if st['spawns'] or st['commit']: print(s['id'],st['stage'],'spawns',st['spawns'],'commit',st['commit'], json.dumps(st['queries']))
"

cd ~/cp-roles/harness-python && python3 -c "
import json;d=json.load(open('harnesses/stages.json'))
for p in d['problems']:
